CREATE OR REPLACE FUNCTION public.reward_follows_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.reward_id is null then return new; end if;

  -- Sent, or paid: either way the money has been instructed and the prize is no
  -- longer "awarded but not yet distributed".
  if new.stage in ('sent', 'paid') and coalesce(old.stage, '') not in ('sent', 'paid') then
    update public.rewards
       set status = 'distributed',
           distributed_at = coalesce(distributed_at, now())
     where id = new.reward_id
       and status <> 'distributed';
  end if;

  return new;
end $function$;
